import math

def term_vols(expiries, fwd_vols):
    """Vol to each expiry from the forward vols of the intervals before it."""
    if len(expiries) != len(fwd_vols):
        raise ValueError("one forward vol per expiry")
    if any(t <= 0 for t in expiries[:1]) or any(b <= a for a, b in zip(expiries, expiries[1:])):
        raise ValueError("expiries must be positive and increase")
    if any(v < 0 for v in fwd_vols):
        raise ValueError("a forward vol cannot be negative")
    out, w, prev = [], 0.0, 0.0
    for T, f in zip(expiries, fwd_vols):
        w += f * f * (T - prev)
        prev = T
        out.append(math.sqrt(w / T))
    return out

