import numpy as np
import pandas as pd

def make_bars(n=1260, seed=2301, mu=0.0003, sigma=0.012, phi=0.06):
    rng = np.random.default_rng(seed)
    eps = sigma * rng.standard_normal(n)
    r = np.empty(n)
    prev = 0.0
    for t in range(n):
        r[t] = mu + phi * prev + eps[t]        # AR(1) log returns: weak momentum
        prev = r[t] - mu
    close = 100 * np.exp(np.cumsum(r))
    prev_close = np.r_[100.0, close[:-1]]
    gap = 0.5 * r + 0.002 * rng.standard_normal(n)   # half of each day's move is overnight
    open_ = prev_close * np.exp(gap)
    w = sigma * 0.5 * np.abs(rng.standard_normal((2, n)))
    high = np.maximum(open_, close) * np.exp(w[0])
    low = np.minimum(open_, close) * np.exp(-w[1])
    volume = np.round(rng.lognormal(np.log(2e6), 0.3, n))
    idx = pd.bdate_range("2019-01-02", periods=n)
    return pd.DataFrame({"open": open_, "high": high, "low": low,
                         "close": close, "volume": volume}, index=idx)

def noise_after(bars, cut, seed=0):
    # the same bars, with every price after row cut scaled by seeded noise
    rng = np.random.default_rng(seed)
    out = bars.copy()
    k = np.exp(0.02 * rng.standard_normal(len(bars) - cut))
    for col in ["open", "high", "low", "close"]:
        out[col] = np.r_[bars[col].to_numpy()[:cut], bars[col].to_numpy()[cut:] * k]
    return out

# six engines, each: bars -> a Series of target positions in [-1, 1]
def honest_engine(bars):
    return np.tanh(50 * bars["close"].pct_change(2)).fillna(0.0)

def peek_engine(bars):
    close = bars["close"]
    return np.tanh(50 * (close.shift(-1) / close - 1)).fillna(0.0)

def scaled_engine(bars):
    # sizes the position by the volatility of the whole sample
    vol = bars["close"].pct_change().std()
    return honest_engine(bars) * 0.01 / vol

def late_engine(bars):
    # honest for its first 300 rows, then it reads tomorrow's close
    out = honest_engine(bars).to_numpy().copy()
    out[300:] = peek_engine(bars).to_numpy()[300:]
    return pd.Series(out, index=bars.index)

def bfill_engine(bars):
    # fills a missing close from the NEXT bar
    close = bars["close"].bfill()
    return np.tanh(50 * close.pct_change()).fillna(0.0)

def ffill_engine(bars):
    # fills a missing close from the PREVIOUS bar
    close = bars["close"].ffill()
    return np.tanh(50 * close.pct_change()).fillna(0.0)
